export const MOD_COUNT = MODS.length;
/** The score multiplier of a set of mods (bit n = MODS[n]). 1 with none, about 3.6 with all of them. */
export function scoreMultiplier(mods: number): number {
  let sum = 0;
  for (let i = 0; i < MODS.length; i++) if ((mods >> i) & 1) sum += MODS[i]!.weight;
  return 1 + sum / 20;
}
